index 000000000..9c8f5c9ab
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/AbstractRecentFractalSwingIndicator.java
@@ -0,0 +1,83 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import org.ta4j.core.Indicator;
+import org.ta4j.core.num.Num;
+
+/**
+ * Shared base for recent fractal swing indicators.
+ * <p>
+ * This base centralizes latest-swing scanning via
+ * {@link FractalDetectionHelper#findLatestConfirmedFractalIndex(Indicator, org.ta4j.core.BarSeries, int, int, int, int, FractalDetectionHelper.Direction)}
+ * while subclasses define direction and local parameter naming.
+ */
+abstract class AbstractRecentFractalSwingIndicator extends AbstractRecentSwingIndicator {
+
+    private final Indicator<Num> indicator;
+
+    /**
+     * Constructor.
+     *
+     * @param indicator    source price indicator
+     * @param unstableBars unstable-bar count contributed by local window settings
+     */
+    protected AbstractRecentFractalSwingIndicator(Indicator<Num> indicator, int unstableBars) {
+        super(indicator, unstableBars);
+        this.indicator = indicator;
+    }
+
+    /**
+     * Validates window configuration and returns the corresponding unstable-bar
+     * count.
+     *
+     * @param precedingBars             required dominating bars before the
+     *                                  candidate
+     * @param followingBars             required dominating bars after the candidate
+     * @param allowedEqualBars          tolerated equal neighbors on each side
+     * @param precedingBarsArgumentName argument label for preceding bars
+     * @param followingBarsArgumentName argument label for following bars
+     * @return unstable-bar contribution
+     * @throws IllegalArgumentException if window values are invalid
+     */
+    protected static int validateWindowConfiguration(int precedingBars, int followingBars, int allowedEqualBars,
+            String precedingBarsArgumentName, String followingBarsArgumentName) {
+        if (precedingBars < 1) {
+            throw new IllegalArgumentException(precedingBarsArgumentName + " must be greater than 0");
+        }
+        if (followingBars < 0) {
+            throw new IllegalArgumentException(followingBarsArgumentName + " must be 0 or greater");
+        }
+        if (allowedEqualBars < 0) {
+            throw new IllegalArgumentException("allowedEqualBars must be 0 or greater");
+        }
+        return precedingBars + followingBars;
+    }
+
+    @Override
+    protected final int detectLatestSwingIndex(int index) {
+        return FractalDetectionHelper.findLatestConfirmedFractalIndex(indicator, getBarSeries(), index, precedingBars(),
+                followingBars(), allowedEqualBars(), direction());
+    }
+
+    /**
+     * @return number of required dominating preceding bars
+     */
+    protected abstract int precedingBars();
+
+    /**
+     * @return number of required dominating following bars
+     */
+    protected abstract int followingBars();
+
+    /**
+     * @return number of tolerated equal neighboring bars on each side
+     */
+    protected abstract int allowedEqualBars();
+
+    /**
+     * @return fractal direction
+     */
+    protected abstract FractalDetectionHelper.Direction direction();
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/AlligatorIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/AlligatorIndicator.java
new file mode 100644
index 000000000..2c9f464fd
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/AlligatorIndicator.java
@@ -0,0 +1,207 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import static org.ta4j.core.num.NaN.NaN;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.Indicator;
+import org.ta4j.core.indicators.averages.SMMAIndicator;
+import org.ta4j.core.indicators.helpers.MedianPriceIndicator;
+import org.ta4j.core.num.Num;
+
+/**
+ * Bill Williams Alligator line indicator.
+ * <p>
+ * The Alligator consists of three displaced smoothed moving averages built from
+ * median price:
+ * <ul>
+ * <li>jaw: SMMA(13) shifted by 8 bars</li>
+ * <li>teeth: SMMA(8) shifted by 5 bars</li>
+ * <li>lips: SMMA(5) shifted by 3 bars</li>
+ * </ul>
+ * This class represents one line. Use the static factories
+ * {@link #jaw(BarSeries)}, {@link #teeth(BarSeries)}, and
+ * {@link #lips(BarSeries)} for the canonical setup.
+ * <p>
+ * Displacement is implemented without look-ahead bias: value at index {@code i}
+ * is read from the smoothed value at {@code i - shift}. Bars before warm-up
+ * return {@code NaN}.
+ * <p>
+ * Interaction note: Bill Williams' fractal breakout logic commonly checks
+ * whether confirmed fractals ({@link FractalHighIndicator},
+ * {@link FractalLowIndicator}) form outside the alligator teeth.
+ *
+ * @see GatorOscillatorIndicator
+ * @see FractalHighIndicator
+ * @see FractalLowIndicator
+ * @see <a href=
+ *      "https://www.investopedia.com/terms/a/alligatorindicator.asp">Investopedia:
+ *      Alligator Indicator</a>
+ * @since 0.22.3
+ */
+public class AlligatorIndicator extends CachedIndicator<Num> {
+
+    public static final int JAW_BAR_COUNT = 13;
+    public static final int JAW_SHIFT = 8;
+    public static final int TEETH_BAR_COUNT = 8;
+    public static final int TEETH_SHIFT = 5;
+    public static final int LIPS_BAR_COUNT = 5;
+    public static final int LIPS_SHIFT = 3;
+
+    private final int barCount;
+    private final int shift;
+    private final Indicator<Num> indicator;
+    private final transient SMMAIndicator smoothedIndicator;
+
+    /**
+     * Constructor.
+     *
+     * @param indicator source indicator (commonly median price)
+     * @param barCount  smoothing window
+     * @param shift     forward displacement (rendered as {@code i - shift})
+     * @throws IllegalArgumentException if {@code indicator} is {@code null},
+     *                                  {@code barCount < 1}, or {@code shift < 0}
+     * @since 0.22.3
+     */
+    public AlligatorIndicator(Indicator<Num> indicator, int barCount, int shift) {
+        super(IndicatorUtils.requireIndicator(indicator, "indicator"));
+        if (barCount < 1) {
+            throw new IllegalArgumentException("barCount must be greater than 0");
+        }
+        if (shift < 0) {
+            throw new IllegalArgumentException("shift must be 0 or greater");
+        }
+        this.barCount = barCount;
+        this.shift = shift;
+        this.indicator = indicator;
+        this.smoothedIndicator = new SMMAIndicator(indicator, barCount);
+    }
+
+    /**
+     * Constructor with series median price.
+     *
+     * @param series   the series
+     * @param barCount smoothing window
+     * @param shift    forward displacement
+     * @since 0.22.3
+     */
+    public AlligatorIndicator(BarSeries series, int barCount, int shift) {
+        this(new MedianPriceIndicator(series), barCount, shift);
+    }
+
+    /**
+     * Creates the default Alligator jaw line.
+     *
+     * @param indicator source indicator
+     * @return jaw line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator jaw(Indicator<Num> indicator) {
+        return new AlligatorIndicator(indicator, JAW_BAR_COUNT, JAW_SHIFT);
+    }
+
+    /**
+     * Creates the default Alligator jaw line from series median price.
+     *
+     * @param series the series
+     * @return jaw line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator jaw(BarSeries series) {
+        return jaw(new MedianPriceIndicator(series));
+    }
+
+    /**
+     * Creates the default Alligator teeth line.
+     *
+     * @param indicator source indicator
+     * @return teeth line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator teeth(Indicator<Num> indicator) {
+        return new AlligatorIndicator(indicator, TEETH_BAR_COUNT, TEETH_SHIFT);
+    }
+
+    /**
+     * Creates the default Alligator teeth line from series median price.
+     *
+     * @param series the series
+     * @return teeth line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator teeth(BarSeries series) {
+        return teeth(new MedianPriceIndicator(series));
+    }
+
+    /**
+     * Creates the default Alligator lips line.
+     *
+     * @param indicator source indicator
+     * @return lips line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator lips(Indicator<Num> indicator) {
+        return new AlligatorIndicator(indicator, LIPS_BAR_COUNT, LIPS_SHIFT);
+    }
+
+    /**
+     * Creates the default Alligator lips line from series median price.
+     *
+     * @param series the series
+     * @return lips line
+     * @since 0.22.3
+     */
+    public static AlligatorIndicator lips(BarSeries series) {
+        return lips(new MedianPriceIndicator(series));
+    }
+
+    @Override
+    protected Num calculate(int index) {
+        if (index < getCountOfUnstableBars()) {
+            return NaN;
+        }
+        final int displacedIndex = index - shift;
+        if (displacedIndex < getBarSeries().getBeginIndex()) {
+            return NaN;
+        }
+        final Num value = smoothedIndicator.getValue(displacedIndex);
+        return IndicatorUtils.isInvalid(value) ? NaN : value;
+    }
+
+    /**
+     * @return source indicator used before smoothing/displacement
+     * @since 0.22.3
+     */
+    public Indicator<Num> getPriceIndicator() {
+        return indicator;
+    }
+
+    /**
+     * @return smoothing window
+     * @since 0.22.3
+     */
+    public int getBarCount() {
+        return barCount;
+    }
+
+    /**
+     * @return displacement amount
+     * @since 0.22.3
+     */
+    public int getShift() {
+        return shift;
+    }
+
+    @Override
+    public int getCountOfUnstableBars() {
+        return smoothedIndicator.getCountOfUnstableBars() + shift;
+    }
+
+    @Override
+    public String toString() {
+        return getClass().getSimpleName() + " barCount: " + barCount + " shift: " + shift;
+    }
+
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalDetectionHelper.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalDetectionHelper.java
new file mode 100644
index 000000000..63864a17e
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalDetectionHelper.java
@@ -0,0 +1,207 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.Indicator;
+import org.ta4j.core.num.Num;
+
+/**
+ * Internal utility for shared fractal window detection logic.
+ */
+final class FractalDetectionHelper {
+
+    enum Direction {
+        HIGH {
+            @Override
+            boolean isCandidateDominant(Num candidate, Num comparison) {
+                return candidate.isGreaterThan(comparison);
+            }
+        },
+        LOW {
+            @Override
+            boolean isCandidateDominant(Num candidate, Num comparison) {
+                return candidate.isLessThan(comparison);
+            }
+        };
+
+        abstract boolean isCandidateDominant(Num candidate, Num comparison);
+    }
+
+    private FractalDetectionHelper() {
+    }
+
+    /**
+     * Scans backwards from the latest confirmable candidate index and returns the
+     * most recent confirmed fractal pivot.
+     *
+     * @param indicator         source indicator
+     * @param series            backing series
+     * @param maxAvailableIndex highest index whose future context is available
+     * @param precedingBars     required dominating bars before candidate
+     * @param followingBars     required dominating bars after candidate
+     * @param allowedEqualBars  tolerated equal neighbors on each side
+     * @param direction         fractal direction
+     * @return latest confirmed pivot index, or {@code -1} when unavailable
+     */
+    static int findLatestConfirmedFractalIndex(Indicator<Num> indicator, BarSeries series, int maxAvailableIndex,
+            int precedingBars, int followingBars, int allowedEqualBars, Direction direction) {
+        if (indicator == null || series == null || direction == null) {
+            return -1;
+        }
+        if (precedingBars < 0 || followingBars < 0 || allowedEqualBars < 0) {
+            return -1;
+        }
+        final int beginIndex = series.getBeginIndex();
+        final int endIndex = series.getEndIndex();
+        if (maxAvailableIndex < beginIndex || maxAvailableIndex > endIndex) {
+            return -1;
+        }
+        final int latestConfirmable = maxAvailableIndex - followingBars;
+        final int earliestCandidate = beginIndex + precedingBars;
+        if (latestConfirmable < earliestCandidate) {
+            return -1;
+        }
+        for (int candidateIndex = latestConfirmable; candidateIndex >= earliestCandidate; candidateIndex--) {
+            if (isConfirmedFractal(indicator, series, candidateIndex, precedingBars, followingBars, maxAvailableIndex,
+                    allowedEqualBars, direction)) {
+                return candidateIndex;
+            }
+        }
+        return -1;
+    }
+
+    /**
+     * Evaluates whether a specific candidate index is a confirmed fractal pivot.
+     *
+     * @param indicator         source indicator
+     * @param series            backing series
+     * @param candidateIndex    candidate pivot index
+     * @param precedingBars     required dominating bars before candidate
+     * @param followingBars     required dominating bars after candidate
+     * @param maxAvailableIndex highest index whose future context is available
+     * @param allowedEqualBars  tolerated equal neighbors on each side
+     * @param direction         fractal direction
+     * @return {@code true} when confirmed, otherwise {@code false}
+     */
+    static boolean isConfirmedFractal(Indicator<Num> indicator, BarSeries series, int candidateIndex, int precedingBars,
+            int followingBars, int maxAvailableIndex, int allowedEqualBars, Direction direction) {
+        if (indicator == null || series == null || direction == null) {
+            return false;
+        }
+        if (precedingBars < 0 || followingBars < 0 || allowedEqualBars < 0) {
+            return false;
+        }
+        final int beginIndex = series.getBeginIndex();
+        final int endIndex = series.getEndIndex();
+        if (candidateIndex < beginIndex || candidateIndex > maxAvailableIndex || candidateIndex > endIndex) {
+            return false;
+        }
+
+        final Num candidateValue = indicator.getValue(candidateIndex);
+        if (IndicatorUtils.isInvalid(candidateValue)) {
+            return false;
+        }
+
+        final int plateauStart = findPlateauStart(indicator, beginIndex, candidateIndex, candidateValue,
+                allowedEqualBars);
+        if (plateauStart < 0) {
+            return false;
+        }
+        final int plateauEnd = findPlateauEnd(indicator, candidateIndex, maxAvailableIndex, candidateValue,
+                allowedEqualBars);
+        if (plateauEnd < 0) {
+            return false;
+        }
+
+        return hasDominatedPrecedingBars(indicator, beginIndex, plateauStart, precedingBars, candidateValue, direction)
+                && hasDominatedFollowingBars(indicator, plateauEnd, maxAvailableIndex, followingBars, candidateValue,
+                        direction);
+    }
+
+    private static int findPlateauStart(Indicator<Num> indicator, int beginIndex, int candidateIndex,
+            Num candidateValue, int allowedEqualBars) {
+        int equalsUsed = 0;
+        int index = candidateIndex;
+        while (index > beginIndex && equalsUsed < allowedEqualBars) {
+            final Num previousValue = indicator.getValue(index - 1);
+            if (IndicatorUtils.isInvalid(previousValue)) {
+                return -1;
+            }
+            if (!previousValue.isEqual(candidateValue)) {
+                break;
+            }
+            equalsUsed++;
+            index--;
+        }
+        if (index > beginIndex) {
+            final Num previousValue = indicator.getValue(index - 1);
+            if (previousValue.isEqual(candidateValue)) {
+                return -1;
+            }
+        }
+        return index;
+    }
+
+    private static int findPlateauEnd(Indicator<Num> indicator, int candidateIndex, int maxAvailableIndex,
+            Num candidateValue, int allowedEqualBars) {
+        int equalsUsed = 0;
+        int index = candidateIndex;
+        while (index < maxAvailableIndex && equalsUsed < allowedEqualBars) {
+            final Num nextValue = indicator.getValue(index + 1);
+            if (IndicatorUtils.isInvalid(nextValue)) {
+                return -1;
+            }
+            if (!nextValue.isEqual(candidateValue)) {
+                break;
+            }
+            equalsUsed++;
+            index++;
+        }
+        if (index < maxAvailableIndex) {
+            final Num nextValue = indicator.getValue(index + 1);
+            if (nextValue.isEqual(candidateValue)) {
+                return -1;
+            }
+        }
+        return index;
+    }
+
+    private static boolean hasDominatedPrecedingBars(Indicator<Num> indicator, int beginIndex, int plateauStartIndex,
+            int precedingBars, Num candidateValue, Direction direction) {
+        if (precedingBars == 0) {
+            return true;
+        }
+        if (plateauStartIndex - precedingBars < beginIndex) {
+            return false;
+        }
+        for (int i = plateauStartIndex - 1; i >= plateauStartIndex - precedingBars; i--) {
+            final Num value = indicator.getValue(i);
+            if (IndicatorUtils.isInvalid(value) || !direction.isCandidateDominant(candidateValue, value)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private static boolean hasDominatedFollowingBars(Indicator<Num> indicator, int plateauEndIndex,
+            int maxAvailableIndex, int followingBars, Num candidateValue, Direction direction) {
+        if (followingBars == 0) {
+            return true;
+        }
+        if (maxAvailableIndex - plateauEndIndex < followingBars) {
+            return false;
+        }
+        for (int i = plateauEndIndex + 1; i <= plateauEndIndex + followingBars; i++) {
+            if (i > maxAvailableIndex) {
+                return false;
+            }
+            final Num value = indicator.getValue(i);
+            if (IndicatorUtils.isInvalid(value) || !direction.isCandidateDominant(candidateValue, value)) {
+                return false;
+            }
+        }
+        return true;
+    }
+}
diff --git a/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalHighIndicator.java b/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalHighIndicator.java
new file mode 100644
index 000000000..39f14ec54
--- /dev/null
+++ b/ta4j-core/src/main/java/org/ta4j/core/indicators/FractalHighIndicator.java
@@ -0,0 +1,121 @@
+/*
+ * SPDX-License-Identifier: MIT
+ */
+package org.ta4j.core.indicators;
+
+import org.ta4j.core.BarSeries;
+import org.ta4j.core.Indicator;
+import org.ta4j.core.indicators.helpers.HighPriceIndicator;
+import org.ta4j.core.num.Num;
+
+/**
+ * Bill Williams Fractal High confirmation indicator.
+ * <p>
+ * A fractal high is confirmed when a candidate bar's high is strictly greater
+ * than the highs in the configured look-back and look-forward windows.
+ * <p>
+ * To avoid look-ahead bias, this indicator emits {@code true} on the
+ * confirmation bar (the current index), not on the candidate pivot bar. The
+ * corresponding pivot index can be obtained through
+ * {@link #getConfirmedFractalIndex(int)}.
+ * <p>
+ * Default settings are {@code 2} preceding bars and {@code 2} following bars,
+ * matching Bill Williams' classic fractal definition from Trading Chaos.
+ * <p>
+ * Interaction note: many Bill Williams systems pair fractal breakouts with the
+ * {@link AlligatorIndicator} and only consider long setups when the confirmed
+ * fractal is above the alligator teeth.
+ *
+ * @see FractalLowIndicator
+ * @see AlligatorIndicator
+ * @see <a href=
+ *      "https://www.investopedia.com/terms/f/fractal.asp">Investopedia: Fractal
+ *      Indicator</a>
+ * @since 0.22.3
+ */
+public class FractalHighIndicator extends AbstractFractalConfirmationIndicator {
+
+    /** Classic Bill Williams preceding-bar count. */
+    public static final int DEFAULT_PRECEDING_BARS = 2;
+
+    /** Classic Bill Williams following-bar count. */
+    public static final int DEFAULT_FOLLOWING_BARS = 2;
+
+    /**
+     * Constructor.
+     *
+     * @param indicator     source indicator, typically {@link HighPriceIndicator}
+     * @param precedingBars bars that must be strictly lower before the pivot
+     * @param followingBars bars that must be strictly lower after the pivot
+     * @throws IllegalArgumentException if {@code indicator} is {@code null},
+     *                                  {@code precedingBars < 1}, or
+     *                                  {@code followingBars < 1}
+     * @since 0.22.3
+     */
+    public FractalHighIndicator(Indicator<Num> indicator, int precedingBars, int followingBars) {
+        super(indicator, precedingBars, followingBars);
+    }
+
+    /**
+     * Constructor with classic Bill Williams defaults:
+     * <ul>
+     * <li>{@code precedingBars} = 2</li>
+     * <li>{@code followingBars} = 2</li>
